    && receipts.every(row => oldReceipts.some(old => old.offerId === row.offerId)
      || oldRows.some(old => old.offerId === row.offerId && ['applied', 'rejected', 'revoked', 'expired'].includes(old.status) && equal(row, externalBotRemoteReceipt(old))));
